package com.scriptles.cabinet.catalog.repository;
import com.scriptles.cabinet.catalog.entity.Collection; import com.scriptles.cabinet.catalog.domain.CatalogEntityStatus; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface CollectionRepository extends JpaRepository<Collection,UUID> { Optional<Collection> findBySlug(String slug); List<Collection> findByStatusAndTitleContainingIgnoreCase(CatalogEntityStatus status,String title,Pageable pageable); Page<Collection> findPageByTitleContainingIgnoreCase(String title,Pageable pageable); @Query("select c from Collection c where c.status = :status and lower(c.title) like lower(concat('%',:query,'%')) order by lower(c.title), c.id") List<Collection> search(@Param("query") String query,@Param("status") CatalogEntityStatus status,Pageable pageable); }
